input.script:
users = list_users({})
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]
times = ["09:00", "09:30", "10:00", "10:30", "11:00", "11:30", "12:00", "12:30", "13:00", "13:30", "14:00", "14:30", "15:00", "15:30", "16:00", "16:30", "17:00"]
per_date = for date in dates {
    avails = for u in users {
        a = boundary retry 2 { return get_availability({ user_id: u.id, date: date }) } catch err {
            return fail("AVAIL_FAILED", err.code + ": " + err.message)
        }
        return a.busy if "busy" in a else []
    }
    busy = fold acc = [] for b in avails { return acc + b }
    intervals = for iv in busy {
        skip if not ("start" in iv) or not ("end" in iv)
        ps = text.split(text.split(iv.start, " ")[0], ":")
        pe = text.split(text.split(iv.end, " ")[0], ":")
        return {
            s: number.parse(ps[0]) * 60 + number.parse(ps[1]),
            e: number.parse(pe[0]) * 60 + number.parse(pe[1])
        }
    }
    candidates = for m in list.range(540, 961, 30) {
        conflict = fold acc = false for iv in intervals {
            return acc or (iv.s < m + 60 and iv.e > m)
        }
        skip if conflict
        return m
    }
    skip if candidates == []
    return { date: date, start_min: candidates[0] }
}
first = per_date[0] if per_date != [] else fail("NO_SLOT", "no free 60-minute slot found in the week")
idx = number.floor((first.start_min - 540) / 30)
start_iso = first.date + "T" + times[idx] + ":00Z"
end_iso = first.date + "T" + times[idx + 2] + ":00Z"
res = submit_result({ answer: { start: start_iso, end: end_iso } })
return { start: start_iso, end: end_iso, recorded: res.recorded }
